describe('Infrastruktur Setup Dokumentation', () => {
  Cypress.env('docu_target_dir', 'Rollen/bilder/screenshots');

  it('R1 legt das neue Dokumentations-Ressort (99) an', () => {
    cy.login('r1');
    cy.visit('/administration/dienststellen');

    cy.get('a').contains('Ressort hinzufügen').click();

    // Formular ausfüllen
    cy.get('input[name="nummer"]').type('99');
    cy.get('input[name="name"]').type('Dokumentations-Ressort');
    cy.get('textarea[name="bemerkungen"]').type('Dies ist ein Test-Ressort für die automatisierte Dokumentation.');
    cy.get('input[name="kapitel"]').type('9999');

    cy.get('form[name="form-03596bc7"]').docuScreenshot('01-ressort-neu-formular');
    cy.get('input[name="btn-save"]').click();

    cy.get('.dienststellen-liste > li').contains('99 Dokumentations-Ressort').should('be.visible');
  });

  it('R1 legt den Dokumentations-Fachbereich (9901) an', () => {
    cy.login('r1');
    cy.visit('/administration/dienststellen');

    // Ressort 99 suchen und "Geschäftsbereich / Projekt hinzufügen" klicken
    cy.get('div').contains('99 Dokumentations-Ressort').parents('li').within(() => {
        cy.get('a[href*="neue-dienststelle-im-ressort"]').click();
    });

    cy.get('input[name="nummer"]').type('9901');
    cy.get('input[name="name"]').type('Dokumentations-Fachbereich');
    cy.get('textarea[name="bemerkungen"]').type('Dies ist ein Test-Fachbereich für die Dokumentation.');

    cy.get('form[name="form-2847db9e"]').docuScreenshot('02-dienststelle-neu-formular');
    cy.get('input[name="btn-save"]').click();

    cy.get('div').contains('9901 Dokumentations-Fachbereich').should('be.visible');
  });

  it('R1 legt den R2-Benutzer für das Ressort 99 an', () => {
    cy.login('r1');
    cy.visit('/administration/benutzerverwaltung/alle-dienststellen');

    // In der Liste das Ressort 99 suchen und "Redakteur hinzufügen" klicken
    cy.get('strong').contains('99 Dokumentations-Ressort').parents('li').within(() => {
        cy.get('a').contains('Redakteur hinzufügen').click();
    });

    // Formular ausfüllen
    cy.get('input[name="user_name"]').type('r2_user');
    cy.get('input[name="last_name"]').type('Redakteur');
    cy.get('input[name="first_name"]').type('R2');
    cy.get('input[name="email"]').type('r2@example.com');
    cy.get('input[name="password"]').type('r2_password');
    cy.get('input[name="password2"]').type('r2_password');

